import pandas as pd
import numpy as np
from collections import defaultdict

# Load data
df = pd.read_csv('chunks_csv/moran_local_no2crime_no2_Q2_2021.csv')
adj = pd.read_csv(ADJACENCY_PATH)

# Drop missing values
df = df.dropna(subset=['value']).reset_index(drop=True)

# Standardize NO2 values to z-scores (population standard deviation)
values = df['value'].values
mean_val = values.mean()
std_val = values.std(ddof=0)
df['z'] = (values - mean_val) / std_val

# Prepare ordered structures
boroughs = df['borough'].tolist()
n = len(boroughs)
z_arr = df['z'].values
borough_to_idx = {b: i for i, b in enumerate(boroughs)}
borough_to_z = {b: z_arr[i] for b, i in borough_to_idx.items()}

# Build symmetric adjacency from list
neighbors = defaultdict(set)
adj = adj.dropna(subset=['borough', 'neighbor'])
for _, row in adj.iterrows():
    b = row['borough']
    neigh = row['neighbor']
    if b == neigh:
        continue
    if b in borough_to_z and neigh in borough_to_z:
        neighbors[b].add(neigh)
        neighbors[neigh].add(b)

# Precompute neighbor index lists for fast access
neighbor_idxs = {}
for b in boroughs:
    neighs = list(neighbors.get(b, set()))
    neighbor_idxs[b] = [borough_to_idx[n] for n in neighs]

# Observed Local Moran's I: z_i * sum(z_j for j in neighbors)
# (binary adjacency weights)
obs_local_I = {}
for b in boroughs:
    idxs = neighbor_idxs[b]
    if len(idxs) == 0:
        obs_local_I[b] = np.nan
    else:
        obs_local_I[b] = borough_to_z[b] * np.sum(z_arr[idxs])

# Permutation test with 999 shuffles
np.random.seed(42)
n_perm = 999
pseudo_local_I = np.empty((n_perm, n))

for p in range(n_perm):
    perm_z = np.random.permutation(z_arr)
    for i, b in enumerate(boroughs):
        idxs = neighbor_idxs[b]
        if len(idxs) == 0:
            pseudo_local_I[p, i] = np.nan
        else:
            pseudo_local_I[p, i] = perm_z[i] * np.sum(perm_z[idxs])

# Compute p-values
p_values = {}
for i, b in enumerate(boroughs):
    obs = obs_local_I[b]
    if np.isnan(obs):
        p_values[b] = np.nan
    else:
        if obs > 0:
            count = np.sum(pseudo_local_I[:, i] >= obs)
        else:
            count = np.sum(pseudo_local_I[:, i] <= obs)
        p_values[b] = (count + 1) / (n_perm + 1)

# Identify significant HH (high-high) and LL (low-low) spots
spots = []
for b in boroughs:
    z = borough_to_z[b]
    obs = obs_local_I[b]
    p = p_values[b]
    if not np.isnan(obs) and obs > 0 and p < 0.05:
        if z > 0:
            spots.append((b, 'HH', obs, p))
        elif z < 0:
            spots.append((b, 'LL', obs, p))

# Print reasoning and computed values
print("Method: Local Moran's I = z_i * sum(z_j for j in neighbors).")
print("Significance tested with 999 permutations (p < 0.05 threshold).")
print("\nAll boroughs (z-score, LocalMoransI, p-value):")
for b in boroughs:
    print(f"{b}: z={borough_to_z[b]:.4f}, LocalMoransI={obs_local_I[b]:.4f}, p={p_values[b]:.4f}")

print("\nIdentified significant hot spots (HH) and cold spots (LL):")
if not spots:
    print("None identified.")
else:
    for b, cat, obs, p in spots:
        print(f"{b} ({cat}): LocalMoransI={obs:.4f}, p={p:.4f}")

# Final answer line
if not spots:
    print("FINAL ANSWER: none")
else:
    parts = []
    for b, cat, obs, p in spots:
        parts.append(f"{b} ({cat}, LocalMoransI={obs:.6f})")
    print("FINAL ANSWER: " + ", ".join(parts))
